        log.info("All %d selected files already parsed (cache hit).", len(selected_files))
        return {
            "parsed_files": existing_pf,
            "messages": state.get("messages", []) + [
                SystemMessage(content="All selected files already parsed.")
            ],
        }

    log.info(
        "Fetching %d files concurrently (max=%d, %d already cached).",
        len(to_fetch), MAX_CONCURRENT_FETCHES, len(already_parsed),
    )

    semaphore = asyncio.Semaphore(MAX_CONCURRENT_FETCHES)

    # ── Progress bar ──────────────────────────────────────────────────────
    pbar = _tqdm_bar(range(len(to_fetch)), total=len(to_fetch), desc="Fetching files")
    pbar_iter = iter(pbar) if hasattr(pbar, "__iter__") else iter(range(len(to_fetch)))

    def _tick():
        try:
            next(pbar_iter)
        except StopIteration:
            pass
        if hasattr(pbar, "update"):
            pbar.update(1)

    # ── Launch all fetch tasks ────────────────────────────────────────────
    tasks = [
        _fetch_one(meta, refresh, semaphore, _tick)
        for meta in to_fetch
    ]
    results = await asyncio.gather(*tasks, return_exceptions=True)

    if hasattr(pbar, "close"):
        pbar.close()

    # ── Collect results (preserve order) ─────────────────────────────────
    new_pf: list[dict] = []
    for meta, result in zip(to_fetch, results):
        if isinstance(result, Exception):
            log.error("Unhandled error fetching %s: %s", meta.get("path"), result)
            new_pf.append({
                "path": meta.get("path", "<unknown>"),
                "ext":  meta.get("ext", ""),
                "parsed": f"<Fetch error: {result}>",
            })
        elif result is not None:
            new_pf.append(result)

    all_pf = existing_pf + new_pf
    print(f"Fetched & parsed {len(new_pf)} files ({len(already_parsed)} from cache).")

    return {
        "parsed_files": all_pf,
        "messages": state.get("messages", []) + [
            SystemMessage(content=f"Fetched & parsed {len(new_pf)} files.")
        ],
    }

async def fetch_repo_metadata_node(state: dict) -> dict:
    """
    First node of the workflow:
    - Reads repository URL from state['url']
    - Optionally reads state['branch'] and state['refresh_cache']
    - Calls GitRepoParser to get metadata tree (with disk caching)
    - Updates state with repo_tree
    """

    repo_url = state.get("url", None)
    if not repo_url:
        return {
            "messages": state["messages"] + [
                SystemMessage(content="No repository URL provided.")
            ]
        }

    branch = state.get("branch") or None
    refresh = bool(state.get("refresh_cache", False))

    try:
        parser = GitRepoParser()
        repo_tree = parser.get_dir_tree(repo_url, branch=branch, refresh=refresh)

        return {
            "repo_tree": repo_tree,
            "messages": state["messages"] + [
                SystemMessage(content=f"Fetched metadata tree for: {repo_url}")
            ]
        }

    except PermissionError as e:
        # GitHub rate limit or auth errors
        err = str(e)
        print(err)
        return {
            "repo_tree": {},
            "messages": state["messages"] + [
                SystemMessage(content=err)
            ]
        }

    except ValueError as e:
        # Bad URL or 404
        err = str(e)
        print(err)
        return {
            "repo_tree": {},
            "messages": state["messages"] + [
                SystemMessage(content=err)
            ]
        }

    except Exception as e:
        err = f"Error fetching repository metadata: {e}"
        print(err)
        return {
            "repo_tree": {},
            "messages": state["messages"] + [
                SystemMessage(content=err)
            ]
        }

