def _check_api_key() -> None:
    """Exit early with a helpful message if no Gemini key is configured."""
    if not os.getenv("GOOGLE_API_KEY") and not os.getenv("GEMINI_API_KEY"):
        print(
            "Error: No Gemini API key found.\n"
            "  Set GOOGLE_API_KEY=<your_key> in your .env file or environment.\n"
            "  See .env.example for details.",
            file=sys.stderr,
        )
        sys.exit(1)

def invalidate(url: str, suffix: str = ".txt") -> None:
    """Delete a single cached entry (silently ignores missing files)."""
    p = _path_for(url, suffix)
    try:
        p.unlink()
    except FileNotFoundError:
        pass

